sap.ui.define([
  "sap/ui/core/mvc/Controller",
  "sap/m/Button",
  "sap/m/Text"
], function (Controller, Button, Text) {
  "use strict";

  return Controller.extend("my.app.controller.Main", {
    onInit: function () {
      const button = new Button(this.createId("saveButton"), {
        text: "{i18n>save}",
        type: "Emphasized",
        press: this.onSave.bind(this)
      });
      this.byId("page").addContent(new Text({ text: "Created in code" }));
      this.byId("page").addContent(button);
    },

    onSave: function () {
      this.byId("saveButton").setText("Saved");
    }
  });
});

