onValidateRange: function (event) {
  if (!event.getParameter("fieldGroupIds").includes("range")) {
    return;
  }
  const start = this.byId("startDate").getDateValue();
  const end = this.byId("endDate").getDateValue();
  const invalid = start && end && end < start;
  this.byId("endDate").setValueState(invalid ? "Error" : "None");
  this.byId("endDate").setValueStateText(invalid ? "End date must be after the start date" : "");
}
